#!/usr/bin/env python3
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
lines=['import Modulus40.SupportCircuitChecks','import Modulus40.ExponentAssignmentValid','','namespace Modulus40','']
for name in ['support','minimum']:
 lines += [f'def {name}Assignment (exponents : ℕ → ℕ) : ℕ → Bool :=',f'  exponentCircuitAssignment {name}NodeCount {name}GateAt {name}AtomLookup exponents','',f'theorem {name}Gates_ordered (index : ℕ) (hi : index < {name}NodeCount) :',f'    ∀ v ∈ ({name}GateAt index).inputs, v ≤ index ∨ {name}NodeCount < v := by',f'  have hraw := supportDescriptions_valid index (by',f'    change index < 36864',f'    change index < {36817 if name=="support" else 36864} at hi', '    omega)',f'  simpa only [{name}GateAt, if_pos hi] using',f'    (supportGateDescriptionAt index).toGate_ordered {name}NodeCount {name}DomainLookup',f'      {name}AtomLookup {name}Domains_valid index hraw.1 hraw.2.{"1"if name=="support"else"2"}','',f'theorem {name}Assignment_valid (exponents : ℕ → ℕ) :',f'    ExponentAssignmentValid {name}NodeCount {name}DomainAt {name}GateAt ({name}Assignment exponents) := by',f'  exact exponentCircuitAssignment_valid {name}NodeCount {name}GateAt {name}AtomLookup',f'    {name}DomainLookup exponents {name}Domains_valid {name}Gates_ordered (by decide +kernel)','',f'theorem {name}Assignment_selector (exponents : ℕ → ℕ) (index prime lower : ℕ) (ray : Bool)',f'    (hi : index < {name}NodeCount)', '    (hg : supportGateDescriptionAt index = .selector prime lower ray) :',f'    {name}Assignment exponents (index + 1) = true ↔', '      if ray then lower ≤ exponents prime else exponents prime = lower := by',f'  have hraw := supportDescriptions_valid index (by', '    change index < 36864',f'    change index < {36817 if name=="support"else 36864} at hi','    omega)',f'  have hsel := hraw.2.{"1"if name=="support"else"2"}', '  rw [hg] at hsel',f'  cases hd : {name}DomainLookup prime with', '  | none => simp [ExponentGate.SelectorValid, hd] at hsel', '  | some domain =>','    simp only [ExponentGate.SelectorValid, hd] at hsel',f'    apply exponentCircuitAssignment_selector {name}NodeCount {name}GateAt {name}AtomLookup',f'      exponents {name}Gates_ordered index prime lower ray domain hi',f'      ({name}Domains_valid prime domain hd) hsel',f'    simp [{name}GateAt, hi, hg, ExponentGate.toGate, {name}DomainAt, hd]','']
lines += ['end Modulus40','']
(ROOT/'Modulus40/SupportAssignment.lean').write_text('\n'.join(lines))
